// Had an idea to add random value to distance of a voronoi cell. Looks interesting.
// Controls:
//     MouseX - distance offset scale (left - regular voronoi, right - fully randomized offset)
//     MouseY - smoothness (bottom - sharp, top - smooth)

// Config:
#define DENSITY 24.
#define MOVE_SPEED 0.5




vec3 rand3(vec2 q) {
    vec3 p = vec3(q.x, q.y, dot(q.xy, vec2(1.234536, 2.132131)));
	vec3 a = fract(p * vec3(123.34,234.34,345.65));
    a+=dot(a, a+34.45);
    return fract(vec3(a.x*a.y,a.y*a.z,a.x*a.z));
}
float smin(float a, float b, float k) {
	float h = clamp((b-a)/k+0.5,0.0,1.0);
	return b+h*(a-b+k*0.5*(h-1.0));
}

struct Voronoi {
    float d;
    float sd;
};

Voronoi voronoi(vec2 p, float smoothness, float baseOffsetScale) {
    vec2 t = floor(p);
    vec2 l = p - t;

    Voronoi r;
    r.d = 100.;
    r.sd = 100.;

    // when baseOffsetScale>0, LIMIT of 1 is not enough sometimes.
    // AFAICT 2 is enough
    const int LIMIT = 2;

    for(int x = -LIMIT;x<=LIMIT;++x)
    for(int y = -LIMIT;y<=LIMIT;++y){
        vec2 o = vec2(x,y);
        vec3 n = rand3(t+o);
        vec2 h = n.xy;
        float d = distance(l, h+o) + n.z * baseOffsetScale;
        if (r.d > d) {
            r.d = d;   
        }
        r.sd = smin(r.sd, d, smoothness);
    }

    // Not sure if this is right but it looks consistent enough
    float MAX_D = sqrt(2.) + baseOffsetScale;

    r.d /= MAX_D;
    r.sd /= MAX_D;

    return r;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float baseOffsetScale = iMouse.x / iResolution.x;
    float smoothness      = iMouse.y / iResolution.y;
    if (length(iMouse.xy) <= 1.) {
        baseOffsetScale = smoothstep(0.,1.,smoothstep(0.,1.,cos(iTime * 3.1415 * 0.25) * 0.5 + 0.5));
        smoothness = 0.;
    }


    Voronoi v = voronoi(fragCoord / iResolution.y * DENSITY + iTime * MOVE_SPEED, smoothness, baseOffsetScale);

    fragColor = vec4(vec3(v.sd),1.0);
}
